<?php
namespace App\Livewire\LMS\Parents;
use App\Models\ParentGuardian; use App\Models\School; use App\Models\Student; use Illuminate\Foundation\Auth\Access\AuthorizesRequests; use Illuminate\Validation\Rule; use Illuminate\Validation\ValidationException; use Jantinnerezo\LivewireAlert\Facades\LivewireAlert; use Livewire\Attributes\Layout; use Livewire\Component; use Throwable;
#[Layout('layouts.lms')]
class Index extends Component { use AuthorizesRequests; public bool $showFormModal=false,$showDeleteModal=false; public ?int $editingId=null,$deletingId=null; public string $firstName='',$lastName='',$phone='',$email='',$address='',$relationship='Guardian'; public array $studentIds=[];
public function mount():void{$this->authorize('viewAny',ParentGuardian::class);} public function create():void{$this->authorize('create',ParentGuardian::class);$this->resetForm();$this->showFormModal=true;} public function edit(ParentGuardian $parent):void{$this->authorize('update',$parent);$this->editingId=$parent->id;$this->firstName=$parent->first_name;$this->lastName=$parent->last_name;$this->phone=$parent->phone??'';$this->email=$parent->email??'';$this->address=$parent->address??'';$this->relationship=$parent->students()->first()?->pivot->relationship??'Guardian';$this->studentIds=$parent->students()->pluck('students.id')->map(fn($id)=>(string)$id)->all();$this->showFormModal=true;}
public function save():void{$parent=$this->editingId?ParentGuardian::findOrFail($this->editingId):null;$this->authorize($parent?'update':'create',$parent??ParentGuardian::class);$schoolId=$parent?->school_id??School::query()->value('id');abort_unless($schoolId,422,'Configure a school before adding a parent.');try{$data=$this->validate(['firstName'=>['required','string','max:100'],'lastName'=>['required','string','max:100'],'phone'=>['nullable','string','max:30'],'email'=>['nullable','email','max:255'],'address'=>['nullable','string','max:1000'],'relationship'=>['required','string','max:50'],'studentIds'=>['array'],'studentIds.*'=>[Rule::exists('students','id')]]);$record=ParentGuardian::updateOrCreate(['id'=>$parent?->id],['school_id'=>$schoolId,'first_name'=>$data['firstName'],'last_name'=>$data['lastName'],'phone'=>$data['phone']?:null,'email'=>$data['email']?:null,'address'=>$data['address']?:null]);$record->students()->sync(collect($data['studentIds'])->mapWithKeys(fn($id)=>[$id=>['relationship'=>$data['relationship'],'is_primary_contact'=>false]])->all());$this->showFormModal=false;$this->resetForm();LivewireAlert::title($parent?'Parent updated':'Parent added')->success()->asToast()->position('top-end')->show();}catch(ValidationException $e){LivewireAlert::title('Check the form')->error()->asToast()->position('top-end')->show();throw $e;}catch(Throwable $e){report($e);LivewireAlert::title('Unable to save parent')->error()->asToast()->position('top-end')->show();}}
public function confirmDelete(ParentGuardian $parent):void{$this->authorize('delete',$parent);$this->deletingId=$parent->id;$this->showDeleteModal=true;} public function delete():void{$parent=ParentGuardian::findOrFail($this->deletingId);$this->authorize('delete',$parent);try{$parent->delete();$this->showDeleteModal=false;$this->deletingId=null;LivewireAlert::title('Parent archived')->success()->asToast()->position('top-end')->show();}catch(Throwable $e){report($e);LivewireAlert::title('Unable to archive parent')->error()->asToast()->position('top-end')->show();}} public function closeModals():void{$this->showFormModal=false;$this->showDeleteModal=false;$this->resetForm();$this->resetErrorBag();}private function resetForm():void{$this->reset(['editingId','deletingId','firstName','lastName','phone','email','address','relationship','studentIds']);$this->relationship='Guardian';$this->resetValidation();} public function render(){return view('livewire.lms.parents.index',['parents'=>ParentGuardian::withCount('students')->orderBy('last_name')->get(),'students'=>Student::where('status','active')->orderBy('last_name')->get()]);}}
